'use strict';
const $=id=>document.getElementById(id);
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:n%100===0?0:2}).format(n/100);
const parseAmount=s=>{const t=String(s).replace(/[$,\s]/g,'');return /^(?:\d+\.?\d{0,2}|\.\d{1,2})$/.test(t)?Number(t):NaN};
function calculate(retail,applied,extraType,extraValue,deposit,extraDollars=0){const standard=[10,5,10].map((r,i)=>applied[i]?Math.round(retail*r/100):0);const extra=(extraType==='percent'?Math.round(retail*extraValue/100):Math.round(extraValue*100))+Math.round(extraDollars*100);const savings=standard.reduce((a,b)=>a+b,0)+extra;const total=Math.max(0,retail-savings);const balance=Math.max(0,total-deposit);const payment=Math.ceil(balance*13/100000);return {standard,extra,savings,total,balance,payment};}
function cycleTile(current,key){const stages={...current};stages[key]=(stages[key]+1)%3;if(stages[key]===2)for(const k of Object.keys(stages))if(k!==key&&stages[k]===2)stages[k]=1;return {stages,plan:Object.keys(stages).find(k=>stages[k]===2)||null}}
const defaults=['50% Off Installation','Initial Consultation Offer','Local Discount','$ off project','% off project'];
let state={retail:0,applied:[false,false,false],names:[...defaults],custom:{dollars:{active:false,value:0},percent:{active:false,value:0}},deposit:0,plan:null,tileStages:{cash:0,monthly:0,promo:0},screen:'investment',sessionId:null,customer:'',rep:''};
const setup=$('setup'),adjust=$('adjust');let hasProject=false;
try{const saved=JSON.parse(sessionStorage.getItem('planner-presentation-v2'));if(saved?.sessionId&&saved.retail>0){state=saved;hasProject=true;$('deposit').value=state.deposit?(state.deposit/100).toLocaleString('en-US'):''}}catch{}
// Update previous default labels in presentations restored from this browser.
state.names=state.names.map((name,i)=>i<3&&[['national promotion','50% off installation'],['same-day savings','initial consultation offer'],['finance discount','national offer','local discount']][i].includes(name.toLowerCase())?defaults[i]:name);
function persist(){if(!hasProject)return;try{sessionStorage.setItem('planner-presentation-v2',JSON.stringify(state))}catch{}}
function record(action,key='',value=0,previous=0){if(!state.sessionId)return;const n=numbers();const i=key.startsWith('standard')?Number(key.slice(-1)):key==='dollars'?3:4;Activity.add({session_id:state.sessionId,customer_label:state.customer,rep_name:state.rep,action,discount_key:key,discount_label:key?state.names[i]:'',value,previous_value:previous,amount_cents:key?(key==='dollars'?Math.round(value*100):Math.round(state.retail*value/100)):0,retail_cents:state.retail,total_cents:n.total});}
function commitCustom(kind){const c=state.custom[kind];const old=c.logged||0;if(c.value!==old){record(old===0?'applied':'updated',kind,c.value,old);c.logged=c.value;persist()}}
function removeCustom(kind){commitCustom(kind);const c=state.custom[kind];const value=c.value;state.custom[kind]={active:false,value:0,logged:0};if(value>0)record('removed',kind,value);render()}

function numbers(retail=state.retail,applied=state.applied,custom=state.custom){return calculate(retail,applied,'percent',custom.percent.active?custom.percent.value:0,state.deposit,custom.dollars.active?custom.dollars.value:0)}
function totals(){let n=numbers();if(state.deposit>n.total){state.deposit=n.total;$('deposit').value=(state.deposit/100).toLocaleString('en-US',{maximumFractionDigits:2});$('depositError').textContent='Down payment adjusted to the new investment total.';n=numbers()}
$('editRetail').textContent=money(state.retail);$('total').textContent=money(n.total);$('savings').textContent=money(n.savings);$('paymentTotal').textContent=money(n.total);$('paymentRetail').textContent=money(state.retail);$('paymentSavings').textContent=money(n.savings);$('balance').textContent=money(n.balance);$('cashBalance').textContent=money(n.balance);$('monthly').textContent='$'+n.payment.toLocaleString('en-US');$('balanceLabel').textContent='Total amount being financed';persist();
for(const kind of ['dollars','percent']){const el=$('amount-'+kind);if(el)el.textContent='−'+money(kind==='dollars'?Math.round(state.custom[kind].value*100):Math.round(state.retail*state.custom[kind].value/100))}}
function closeDiscounts(){$('discountPopover').hidden=true;$('discountTrigger').setAttribute('aria-expanded','false')}
function removeButton(label,action){const b=document.createElement('button');b.type='button';b.className='remove-discount';b.setAttribute('aria-label','Remove '+label);b.textContent='×';b.onclick=action;return b}
function render(){$('customerReference').textContent=state.customer||'';$('customerReference').hidden=!state.customer;totals();const n=numbers();$('discountRows').replaceChildren();$('discountOptions').replaceChildren();state.names.forEach((name,i)=>{const kind=i===3?'dollars':'percent';const on=i<3?state.applied[i]:state.custom[kind].active;const option=document.createElement('button');option.type='button';option.className='discount-option';option.setAttribute('aria-pressed',String(on));option.textContent=(on?'✓  ':'＋  ')+name;option.onclick=()=>{if(i<3)toggleDiscount(i);else if(!state.custom[kind].active){state.custom[kind]={active:true,value:0};render()}closeDiscounts();if(i>=3)$('input-'+kind)?.focus()};$('discountOptions').append(option);if(i>=3||!on)return;const row=document.createElement('div');row.className='discount';const tick=document.createElement('span');tick.className='tick';tick.textContent='✓';const label=document.createElement('span');label.className='name';label.textContent=name;const amount=document.createElement('strong');amount.textContent='−'+money(n.standard[i]);row.append(tick,label,amount,removeButton(name,()=>toggleDiscount(i)));$('discountRows').append(row)});
$('customRows').replaceChildren();for(const [kind,i] of [['dollars',3],['percent',4]]){const c=state.custom[kind];if(!c.active)continue;const wrap=document.createElement('div');const row=document.createElement('div');row.className='discount custom-discount';const label=document.createElement('label');label.className='name';label.htmlFor='input-'+kind;label.textContent=state.names[i];const field=document.createElement('div');field.className='custom-input';const unit=document.createElement('span');unit.textContent=kind==='dollars'?'$':'%';const input=document.createElement('input');input.id='input-'+kind;input.inputMode='decimal';input.autocomplete='off';input.value=c.value?String(c.value):'';input.setAttribute('aria-describedby','error-'+kind);const amount=document.createElement('strong');amount.id='amount-'+kind;amount.textContent='−'+money(kind==='dollars'?Math.round(c.value*100):Math.round(state.retail*c.value/100));const error=document.createElement('p');error.id='error-'+kind;error.className='error';error.setAttribute('aria-live','polite');input.oninput=()=>{const v=input.value.trim()===''?0:parseAmount(input.value);const proposed={...state.custom,[kind]:{active:true,value:v}};if(!Number.isFinite(v)||v<0||numbers(state.retail,state.applied,proposed).savings>state.retail){error.textContent='Enter savings that keep the investment at $0 or above.';input.setAttribute('aria-invalid','true');return}error.textContent='';input.removeAttribute('aria-invalid');state.custom[kind].value=v;totals()};input.onblur=()=>{commitCustom(kind);input.value=state.custom[kind].value?state.custom[kind].value.toLocaleString('en-US',{maximumFractionDigits:2}):'';error.textContent='';input.removeAttribute('aria-invalid')};field.append(unit,input);row.append(label,field,amount,removeButton(state.names[i],()=>removeCustom(kind)));wrap.append(row,error);$('customRows').append(wrap)}
$('investment').hidden=state.screen!=='investment';$('payment').hidden=state.screen!=='payment';$('navInvestment').classList.toggle('active',state.screen==='investment');$('navPayment').classList.toggle('active',state.screen==='payment');document.querySelectorAll('.card').forEach(c=>{const stage=state.tileStages[c.dataset.plan];const selected=stage===2;c.classList.toggle('selected',selected);c.classList.toggle('expanded',stage>0);c.setAttribute('aria-pressed',String(selected));c.setAttribute('aria-expanded',String(stage>0));c.querySelector('.card-details').hidden=stage===0})}
function screen(s){closeDiscounts();state.screen=s;render();window.scrollTo({top:0,behavior:'smooth'})}
function openSetup(fresh=false){$('identityFields').hidden=hasProject;$('repFields').hidden=hasProject;$('customerInput').required=!hasProject;$('repInput').required=!hasProject;$('customerInput').value=hasProject?state.customer:'';try{$('repInput').value=state.rep||localStorage.getItem('planner-rep')||''}catch{$('repInput').value=state.rep||''}$('retailInput').value=fresh?'':(state.retail/100||'').toLocaleString('en-US');$('cancelSetup').hidden=!hasProject;$('setupError').textContent='';setup.showModal();$(hasProject?'retailInput':'customerInput').focus()}
$('setupForm').onsubmit=e=>{e.preventDefault();const amount=parseAmount($('retailInput').value);if(!Number.isFinite(amount)||amount<=0||amount>10000000){$('setupError').textContent='Enter a price greater than $0 and no more than $10,000,000.';return}const candidate=Math.round(amount*100);if(numbers(candidate).savings>candidate){$('setupError').textContent='Reduce additional savings before lowering the retail price.';return}const first=!hasProject;if(first){const customer=$('customerInput').value.trim(),rep=$('repInput').value.trim();if(!customer||!rep){$('setupError').textContent='Enter a customer name and sales rep name.';return}state.sessionId=Activity.uid();state.customer=Activity.shorten(customer);state.rep=rep;try{localStorage.setItem('planner-rep',rep)}catch{}$('customerInput').value=state.customer}state.retail=candidate;hasProject=true;if(first)record('presented');setup.close();render()};setup.addEventListener('cancel',e=>{if(!hasProject)e.preventDefault()});$('cancelSetup').onclick=()=>setup.close();$('editRetail').onclick=()=>openSetup();
$('next').onclick=()=>screen('payment');$('back').onclick=()=>screen('investment');$('navPayment').onclick=()=>screen('payment');$('navInvestment').onclick=()=>screen('investment');document.querySelectorAll('.card').forEach(c=>c.onclick=()=>{const next=cycleTile(state.tileStages,c.dataset.plan);state.tileStages=next.stages;state.plan=next.plan;render()});
$('deposit').addEventListener('input',()=>{const raw=$('deposit').value;const v=raw.trim()===''?0:parseAmount(raw);const total=numbers().total;if(!Number.isFinite(v)||v<0||Math.round(v*100)>total){$('depositError').textContent='Enter a down payment between $0 and '+money(total)+'.';return}$('depositError').textContent='';state.deposit=Math.round(v*100);totals()});$('deposit').addEventListener('blur',()=>{$('deposit').value=state.deposit?(state.deposit/100).toLocaleString('en-US',{maximumFractionDigits:2}):'';$('depositError').textContent=''});
function openAdjust(){closeDiscounts();$('discountSettings').replaceChildren();state.names.forEach((name,i)=>{const row=document.createElement('label');row.className='rename-row';const caption=document.createElement('span');caption.textContent=defaults[i]+(i<3?' · '+[10,5,10][i]+'% off':'');const input=document.createElement('input');input.type='text';input.value=name;input.id='name'+i;input.maxLength=40;input.setAttribute('aria-label','Rename '+defaults[i]);row.append(caption,input);$('discountSettings').append(row)});adjust.showModal()}
$('settings').onclick=openAdjust;$('closeAdjust').onclick=()=>adjust.close();$('adjustForm').onsubmit=e=>{e.preventDefault();state.names=defaults.map((name,i)=>$('name'+i).value.trim()||name);adjust.close();render()};
$('reset').onclick=()=>{if(!confirm('Start a new presentation and clear these amounts?'))return;state={...state,retail:0,applied:[false,false,false],custom:{dollars:{active:false,value:0},percent:{active:false,value:0}},deposit:0,plan:null,tileStages:{cash:0,monthly:0,promo:0},screen:'investment',sessionId:null,customer:'',rep:''};hasProject=false;try{sessionStorage.removeItem('planner-presentation-v2')}catch{}$('deposit').value='';$('depositError').textContent='';$('discountError').textContent='';closeDiscounts();render();openSetup(true)};
$('retailInput').addEventListener('input',e=>{const input=e.target;const raw=input.value.replace(/,/g,'');if(!/^\d*(\.\d{0,2})?$/.test(raw))return;const before=input.value.slice(0,input.selectionStart).replace(/,/g,'').length;const parts=raw.split('.');parts[0]=parts[0].replace(/\B(?=(\d{3})+(?!\d))/g,',');input.value=parts.join('.');let pos=0,count=0;while(pos<input.value.length&&count<before){if(input.value[pos]!==',')count++;pos++}input.setSelectionRange(pos,pos)});
function toggleDiscount(i){const next=[...state.applied];next[i]=!next[i];if(numbers(state.retail,next).savings>state.retail){$('discountError').textContent='Reduce additional savings before applying this discount.';return}$('discountError').textContent='';state.applied=next;record(next[i]?'applied':'removed','standard'+i,[10,5,10][i]);render()}
$('discountTrigger').onclick=()=>{const open=$('discountPopover').hidden;$('discountPopover').hidden=!open;$('discountTrigger').setAttribute('aria-expanded',String(open))};$('closeDiscounts').onclick=closeDiscounts;document.addEventListener('click',e=>{if(!e.target.closest('.discount-anchor'))closeDiscounts()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('discountPopover').hidden){closeDiscounts();$('discountTrigger').focus()}});
render();Activity.status();void Activity.flush();if(!hasProject)openSetup(true);

addEventListener('pagehide',()=>{for(const kind of ['dollars','percent'])if(state.custom[kind].active)commitCustom(kind);persist()});

$('repInput').addEventListener('input',()=>{try{localStorage.setItem('planner-rep',$('repInput').value.trim())}catch{}});
